static int test_llrintl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(llrintl_vec)/sizeof(llrintl_vec[0]); i++) {
        long long y = llrintl(llrintl_vec[i].x);
        result += check_long_long("llrintl", llrintl_vec[i].line, llrintl_vec[i].y, y);
    }
    return result;
}

