static int test_fminl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(fminl_vec)/sizeof(fminl_vec[0]); i++) {
        long double y = fminl(fminl_vec[i].x0, fminl_vec[i].x1);
        result += check_long_double("fminl", fminl_vec[i].line, FMINL_PREC, fminl_vec[i].y, y);
    }
    return result;
}

