static int test_erfl(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(erfl_vec)/sizeof(erfl_vec[0]); i++) {
        long double y = erfl(erfl_vec[i].x);
        result += check_long_double("erfl", erfl_vec[i].line, ERFL_PREC, erfl_vec[i].y, y);
    }
    return result;
}
