static int test_lgammal(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(lgammal_vec)/sizeof(lgammal_vec[0]); i++) {
        long double y = lgammal(lgammal_vec[i].x);
        result += check_long_double("lgammal", lgammal_vec[i].line, LGAMMAL_PREC, lgammal_vec[i].y, y);
    }
    return result;
}
