static int test_log2l(void) {
    unsigned int i;
    int result = 0;
    for (i = 0; i < sizeof(log2l_vec)/sizeof(log2l_vec[0]); i++) {
        long double y = log2l(log2l_vec[i].x);
        result += check_long_double("log2l", log2l_vec[i].line, LOG2L_PREC, log2l_vec[i].y, y);
    }
    return result;
}
